head.b:skin:
/* SaeMedia v1.2 - tema Blogger portal berita */
/* -----------------------------------------------
<Variable name="schemeColor" description="Warna utama (merah)" type="color" default="#d9091b" value="#d9091b"/>
<Variable name="secondColor" description="Warna kedua (ungu)" type="color" default="#3920c9" value="#3920c9"/>
<Variable name="hoverColor" description="Warna hover menu" type="color" default="#f1c40f" value="#f1c40f"/>
<Variable name="footerBg" description="Latar footer" type="color" default="#ffffff" value="#ffffff"/>
----------------------------------------------- */

:root{--red:$(schemeColor);--blue:$(secondColor);--yel:$(hoverColor);--bg:#fff;--bg2:#f8f8f8;--txt:#000;--grey:#555;--grey2:#666;--bd:#e0e0e0;--soft:rgba(0,0,0,.05);--hdr:#fff;--nav1:$(schemeColor);--nav2:$(secondColor);--ft:$(footerBg);--pop1:#efefef;--pop2:#dddddd;--shadow:0 6px 24px rgba(0,0,0,.14)}
body.dark,html.sm-dark-pre body{--bg:#111;--bg2:#000;--txt:#eee;--grey:#9e9e9e;--grey2:#e0e0e0;--bd:#444;--soft:rgba(255,255,255,.07);--hdr:#222;--nav1:#333;--nav2:#222;--ft:#1b1b1b;--pop1:#222;--pop2:#2c2c2c;--yel:#f1c40f}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;font:400 14px/1.5 Poppins,Arial,sans-serif;background:var(--bg);color:var(--txt);overflow-wrap:break-word}
a{color:var(--txt);text-decoration:none;transition:color .2s}
a:hover{color:var(--red)}
img{max-width:100%;height:auto;border:0;vertical-align:middle}
h1,h2,h3,h4{font-weight:500;line-height:1.4;margin:0 0 10px}
p{margin:0 0 20px}
button{font:inherit;cursor:pointer}
ul{margin:0;padding:0;list-style:none}
.sm-c{max-width:1050px;margin:0 auto;padding:0 16px}
.sm-hide,.sm-cfg{display:none!important}
.section,.widget{margin:0;padding:0}
.widget .widget-content{margin:0}
.sm-skip{position:absolute;left:-9999px}
.sm-skip:focus{left:16px;top:8px;z-index:100000;background:#fff;padding:8px}

/* ===== Header ===== */
.sm-hd{position:sticky;top:0;z-index:999;background:var(--hdr);box-shadow:0 1px 0 rgba(0,0,0,.04)}
.sm-top{height:60px;display:flex;align-items:center;gap:16px}
.sm-logo{flex:0 1 auto;min-width:0;display:flex;align-items:center}
.sm-logo .widget{line-height:0}
.sm-logo img{max-height:40px;width:auto;display:block}
.sm-logo-t{display:inline-block;font:700 27px/1.15 Poppins,Arial,sans-serif;letter-spacing:-.5px;text-transform:uppercase;background:linear-gradient(80deg,var(--red),var(--blue));-webkit-background-clip:text;background-clip:text;color:transparent;white-space:nowrap}
.sm-logo h1,.sm-logo p{margin:0;line-height:1}
.sm-logo .sm-desc{display:none}
.sm-tr{margin-left:auto;display:flex;align-items:center;gap:12px}
.sm-date{font-size:13px;padding-right:16px;border-right:1px solid var(--bd);white-space:nowrap}
.sm-search{position:relative;margin:0}
.sm-search input{width:230px;height:34px;border-radius:20px;border:1px solid var(--bd);background:var(--soft);padding:0 38px 0 16px;font:400 13px Poppins,Arial,sans-serif;color:var(--txt);outline:0}
.sm-search input:focus{border-color:var(--blue)}
.sm-search button{position:absolute;right:4px;top:2px;width:30px;height:30px;border:0;background:none;color:var(--txt);padding:0;display:flex;align-items:center;justify-content:center}
.sm-ib{width:34px;height:34px;display:inline-flex;align-items:center;justify-content:center;background:none;border:0;padding:0;color:var(--txt);border-radius:4px}
.sm-ib:hover{color:var(--red)}
.sm-ib svg{width:22px;height:22px}
.sm-burger,.sm-sbtn{display:none}
.sm-gw{position:relative}
.sm-gridm{position:absolute;right:-10px;top:calc(100% + 6px);background:var(--bg);box-shadow:var(--shadow);padding:14px 18px;display:none;grid-template-columns:repeat(2,minmax(110px,auto));gap:4px 34px;z-index:20;border-radius:2px}
.sm-gw.open .sm-gridm{display:grid}
.sm-gw.open .sm-gbtn{color:var(--red)}
.sm-gridm a,.sm-sub a{display:block;font-size:13px;line-height:2.1;white-space:nowrap}
/* nav */
.sm-nav{background:linear-gradient(80deg,var(--nav1) 0%,var(--nav2) 100%);height:44px}
.sm-menu{display:flex;align-items:center;gap:30px;height:44px}
.sm-menu>li{position:relative;height:44px;display:flex;align-items:center}
.sm-menu>li>a{color:#fff;font-size:14px;font-weight:500;height:44px;display:flex;align-items:center;gap:4px;position:relative;white-space:nowrap}
.sm-menu>li:hover>a,.sm-menu>li.on>a{color:var(--yel)!important;box-shadow:inset 0 -3px 0 var(--yel)}
.sm-menu>li>a svg{width:12px;height:12px;transition:transform .2s}
.sm-menu>li:hover>a svg{transform:rotate(180deg)}
.sm-dot>a::after{content:'';position:absolute;top:11px;right:-8px;width:6px;height:6px;border-radius:50%;background:#26c6da}
.sm-bdg{position:absolute;top:1px;right:-14px;font-size:8px;line-height:1;padding:2px 4px;border-radius:2px;background:#e00;color:#fff;font-weight:500;letter-spacing:.2px}
.sm-bdg.g{background:#27ae60}
.sm-sub{position:absolute;top:100%;left:-16px;background:var(--bg);box-shadow:var(--shadow);padding:12px 18px;display:none;grid-template-columns:repeat(2,minmax(110px,auto));gap:2px 34px;z-index:30;border-radius:0 0 2px 2px}
.sm-sub.one{grid-template-columns:minmax(160px,auto)}
.sm-menu>li:hover>.sm-sub{display:grid}
.sm-menu>li.sm-right>.sm-sub{left:auto;right:-16px}

/* ===== Breaking news ===== */
.sm-bn{margin-top:20px;height:54px;background:var(--red);display:flex;overflow:hidden;color:#fff;font-size:14px}
.sm-bn-l{flex:0 0 auto;background:#000;display:flex;align-items:center;padding:0 34px 0 10px;font-weight:600;clip-path:polygon(0 0,100% 0,calc(100% - 22px) 100%,0 100%);white-space:nowrap}
.sm-bn-t{flex:1;min-width:0;overflow:hidden;position:relative}
.sm-bn-in{position:absolute;top:0;left:0;height:100%;display:flex;align-items:center;gap:34px;width:max-content;animation:smtick var(--dur,40s) linear infinite;will-change:transform}
.sm-bn-t:hover .sm-bn-in{animation-play-state:paused}
.sm-bn-i{display:flex;align-items:center;gap:10px;width:290px;color:#fff;font-size:12px;font-weight:500;line-height:1.35}
.sm-bn-i:hover{color:var(--yel)}
.sm-bn-i img{width:32px;height:32px;object-fit:cover;flex:0 0 32px;border-radius:2px;background:rgba(255,255,255,.2)}
.sm-bn-i span{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
@keyframes smtick{from{transform:translateX(0)}to{transform:translateX(-50%)}}

/* ===== Ads ===== */
.sm-ad{text-align:center;line-height:0}
.sm-ad .widget-content{line-height:normal}
.sm-ad .widget>h2,.sm-ad .widget>h3,.sm-ad .title{display:none}
.sm-ad img,.sm-ad iframe{max-width:100%;height:auto}
.sm-ph{display:flex;align-items:center;justify-content:center;margin:0 auto;max-width:100%;background:repeating-linear-gradient(45deg,var(--soft),var(--soft) 10px,transparent 10px,transparent 20px);border:1px dashed var(--bd);color:var(--grey);font-size:13px;line-height:1.3;text-align:center}
.sm-ad-hd{margin:20px 0 0}
.sm-ad-hd .sm-ph{width:970px;height:250px}
.sm-ad-list{margin:0 0 20px}
.sm-ad-list .sm-ph{width:468px;height:60px}
.sm-ad-side .sm-ph{width:325px;height:300px}
.sm-side .sm-ad-side{margin-bottom:20px}
/* floating */
.sm-fl{position:fixed;top:120px;width:160px;z-index:998;display:none}
.sm-fl-l{left:calc(50% - 525px - 176px)}
.sm-fl-r{right:calc(50% - 525px - 176px)}
.sm-fl .sm-ph{width:160px;height:600px;background-color:var(--bg)}
.sm-x{position:absolute;top:-10px;right:-10px;width:24px;height:24px;border-radius:50%;border:2px solid #fff;background:#000;color:#fff;font-size:14px;line-height:1;display:flex;align-items:center;justify-content:center;z-index:2;padding:0}
@media (min-width:1420px){.sm-fl{display:block}.sm-fl.closed{display:none}}
/* mobile very-top parallax */
.sm-vt{display:none;background:#000;position:relative}
.sm-vt-bar{display:flex;align-items:center;justify-content:center;height:26px;color:#fff;font-size:11px;letter-spacing:.3px;position:relative;z-index:3;background:#000}
.sm-vt-bar .sm-x{position:absolute;top:1px;right:8px;width:22px;height:22px;border:0;background:#333}
.sm-px{position:relative;clip-path:inset(0 0 0 0);overflow:hidden}
.sm-vt .sm-px{height:330px}
.sm-vt .sm-px-in{top:191px}
.sm-px-in{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);width:max-content;max-width:100vw}
.sm-vt .sm-ph{width:325px;height:300px;background-color:#111;color:#bbb}

/* ===== Layout grid ===== */
.sm-main{padding-top:20px}
.sm-grid{display:grid;grid-template-columns:minmax(0,672fr) minmax(0,326fr);column-gap:20px;row-gap:0;grid-template-areas:"ma sc"}
.is-home .sm-grid{grid-template-areas:"ma sa" "fw fw" "mc sc"}
.sm-ma{grid-area:ma;min-width:0}
.sm-sa{grid-area:sa;min-width:0}
.sm-fw{grid-area:fw;min-width:0}
.sm-mc{grid-area:mc;min-width:0}
.sm-sc{grid-area:sc;min-width:0}
body:not(.is-home) .home-only{display:none!important}
.sm-side{align-self:start;position:sticky;top:124px}
.is-home .sm-sa{position:static}
.sm-fw .widget{margin-bottom:20px}
.sm-side .widget{margin-bottom:20px}

/* ===== Titles ===== */
.sm-st{display:flex;align-items:center;gap:10px;font-size:18px;font-weight:500;line-height:1.4;margin:0 0 16px;color:var(--txt)}
.sm-st::before{content:'';flex:0 0 10px;height:15px;background:var(--blue)}
.sm-st.noicon::before{display:none}
.sm-st img{max-height:32px;width:auto}
.sm-st-img::before{display:none}
.sm-wt{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:16px}
.sm-wt .sm-st{margin:0}
.sm-wt-a{color:inherit;display:flex}
.sm-wt-a svg{width:16px;height:16px}
.sm-wdesc{font-size:13px;color:var(--grey);margin:-8px 0 12px;line-height:1.5}
.sm-ptitle{font-size:24px;font-weight:500;margin:0 0 20px}
.sm-ptitle small{display:block;font-size:13px;color:var(--grey);font-weight:400}

/* chip + meta */
.sm-chip{display:inline-block;background:var(--red);color:#fff!important;font-size:11px;line-height:1;padding:5px;border-radius:2px;font-weight:500;white-space:nowrap}
.sm-chip:hover{background:var(--blue)}
.sm-meta{display:flex;align-items:center;flex-wrap:wrap;gap:8px;font-size:11px;color:var(--grey)}
.sm-meta .sm-chip{padding:4px 5px}

/* ===== Slider ===== */
.sm-sl{margin-bottom:20px}
.sm-sl-m{position:relative;height:384px;overflow:hidden;background:#222}
.sm-sl-tr{display:flex;height:100%;transition:transform .55s ease}
.sm-sl-s{flex:0 0 100%;position:relative;height:100%;display:block;color:#fff}
.sm-sl-s img{width:100%;height:100%;object-fit:cover;display:block}
.sm-sl-info{position:absolute;left:0;right:0;bottom:0;padding:40px 16px 16px;background:linear-gradient(0deg,rgba(0,0,0,.9),rgba(0,0,0,0) 100%)}
.sm-sl-info h3{font-size:22px;line-height:1.4;margin:5px 0;color:#fff}
.sm-sl-info h3 a{color:#fff}
.sm-sl-info h3 a:hover{color:var(--yel)}
.sm-sl-info time{font-size:11px;color:#ddd}
.sm-sl-th{overflow:hidden}
.sm-sl-thtr{display:flex;transition:transform .4s ease}
.sm-sl-t{flex:0 0 25%;border-top:4px solid #000;background:var(--soft);cursor:pointer;display:block;color:var(--txt)}
.sm-sl-t.on{border-top-color:var(--red)}
.sm-sl-t img{display:block;width:100%;aspect-ratio:168/106;object-fit:cover}
.sm-sl-t span{display:block;padding:10px;min-height:79px}
.sm-sl-t span b{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;font-size:14px;font-weight:500;line-height:1.4}

/* ===== Post list (box item) ===== */
.sm-post{margin:0 0 20px}
.sm-box{display:flex;align-items:center;gap:16px}
.sm-thumb{flex:0 0 25%;max-width:25%;display:block;border-radius:2px;overflow:hidden;background:var(--soft);position:relative}
.sm-thumb img{display:block;width:100%;aspect-ratio:168/121;object-fit:cover;transition:transform .3s}
.sm-post:hover .sm-thumb img{transform:scale(1.04)}
.sm-box-c{flex:1;min-width:0}
.sm-et{font-size:18px;font-weight:500;line-height:1.4;margin:0 0 10px}
.sm-ex{font-size:12px;color:var(--grey);margin:8px 0 0;display:-webkit-box;-webkit-line-clamp:1;-webkit-box-orient:vertical;overflow:hidden}
.sm-more-wrap{text-align:center;margin:10px 0 20px}
.sm-more{display:inline-block;background:var(--blue);color:#fff!important;padding:8px 16px;border-radius:2px;font-weight:500;font-size:14px;border:0}
.sm-more:hover{opacity:.9}
.sm-more.load{opacity:.6;pointer-events:none}
.sm-nomore{font-size:13px;color:var(--grey);text-align:center;margin:10px 0 20px}
.sm-empty{padding:30px 0;color:var(--grey)}

/* ===== Carousel ===== */
.sm-cr{position:relative}
.sm-cr-vp{overflow:hidden}
.sm-cr-tr{display:flex;gap:16px;transition:transform .45s ease}
.sm-cr-i{flex:0 0 calc((100% - 16px * (var(--n,3) - 1)) / var(--n,3));min-width:0;background:var(--soft);display:block}
.sm-cr-img{position:relative;display:block;overflow:hidden}
.sm-cr-img img{display:block;width:100%;aspect-ratio:16/10;object-fit:cover;transition:transform .3s}
.sm-cr-i:hover .sm-cr-img img{transform:scale(1.05)}
.sm-cr-img .sm-chip,.sm-gb-i .sm-chip{position:absolute;left:8px;bottom:8px}
.sm-cr-t{display:block;padding:10px;min-height:79px;color:var(--txt)}
.sm-cr-t b{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;font-size:14px;font-weight:500;line-height:1.4}
.sm-arr{position:absolute;top:50%;width:48px;height:48px;border-radius:50%;background:#fff;color:#000;border:0;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 10px rgba(0,0,0,.25);z-index:3;transform:translateY(-50%);padding:0}
.sm-arr svg{width:18px;height:18px}
.sm-arr.p{left:6px}
.sm-arr.n{right:6px}
.sm-arr:hover{background:var(--yel)}
.sm-gbox{padding:16px;border-radius:2px;background:linear-gradient(137deg,var(--red) 0%,var(--blue) 100%);color:#fff}
.sm-gbox .sm-st,.sm-gbox .sm-wt-a,.sm-gbox .sm-cr-t{color:#fff}
.sm-gbox .sm-st::before{background:#8bc34a}
.sm-gbox .sm-cr-i{background:rgba(0,0,0,.12)}
.sm-gbox .sm-cr-i:hover .sm-cr-t{color:var(--yel)}
.sm-mod{margin:0 0 20px}

/* grid box (overlay cards) */
.sm-gb{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}
.sm-gb-i{position:relative;display:block;overflow:hidden;color:#fff;border-radius:2px}
.sm-gb-i img{display:block;width:100%;aspect-ratio:148/220;object-fit:cover;transition:transform .3s}
.sm-gb-i:hover img{transform:scale(1.05)}
.sm-gb-i::after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(0,0,0,.85) 0%,rgba(0,0,0,0) 60%)}
.sm-gb-c{position:absolute;left:0;right:0;bottom:0;padding:10px;z-index:2}
.sm-gb-c .sm-chip{position:static;margin-bottom:6px}
.sm-gb-c b{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;font-size:14px;font-weight:500;line-height:1.4;color:#fff}
.sm-gbox2{padding:16px;border-radius:2px;color:#fff}
.sm-gbox2 .sm-st{color:#fff}
.sm-gbox2 .sm-st::before{background:var(--yel)}

/* side big (1 besar + kecil) */
.sm-sb-big{position:relative;display:block;overflow:hidden;margin-bottom:12px;border-radius:2px}
.sm-sb-big img{display:block;width:100%;aspect-ratio:326/205;object-fit:cover}
.sm-sb-big::after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(0,0,0,.85),rgba(0,0,0,0) 60%)}
.sm-sb-bc{position:absolute;left:0;right:0;bottom:0;padding:12px;z-index:2;color:#fff}
.sm-sb-bc b{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:14px;font-weight:500;line-height:1.4}
.sm-sb-bc time{font-size:11px;color:#ddd}
.sm-sm{display:flex;gap:12px;align-items:center;margin-bottom:12px}
.sm-sm-img{flex:0 0 80px;border-radius:2px;overflow:hidden;display:block}
.sm-sm-img img{display:block;width:80px;height:80px;object-fit:cover}
.sm-sm b{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:14px;font-weight:500;line-height:1.4}
.sm-sm time{font-size:11px;color:var(--grey)}

/* popular */
.sm-pop{padding:16px;border-radius:2px;background:linear-gradient(1deg,var(--pop1) 0%,var(--pop2) 100%)}
.sm-pop .widget-content{margin:0}
.sm-pi{display:flex;gap:10px;align-items:center;margin-top:10px;position:relative}
.sm-pn{flex:0 0 60px;height:60px;background:var(--red);color:#fff;font-size:20px;font-weight:500;display:flex;align-items:center;justify-content:center}
.sm-pi-c{min-width:0;flex:1}
.sm-pi-c b{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:14px;font-weight:500;line-height:1.4}
.sm-pi-c time{font-size:11px;color:var(--grey)}
.sm-pi.first{display:block;margin-top:0}
.sm-pi.first .sm-pi-img{display:block;position:relative;overflow:hidden}
.sm-pi.first .sm-pi-img img{display:block;width:100%;aspect-ratio:294/205;object-fit:cover}
.sm-pi.first .sm-pi-img::after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(0,0,0,.8),rgba(0,0,0,0) 55%)}
.sm-pi.first .sm-pi-row{position:absolute;left:0;right:0;bottom:0;display:flex;gap:10px;align-items:center;z-index:2;padding:0 10px 10px 10px}
.sm-pi.first .sm-pi-c b,.sm-pi.first .sm-pi-c b a{color:#fff}
.sm-pi.first .sm-pi-c time{color:#ddd}
.sm-pi.first .sm-pn{flex-basis:40px;height:40px;font-size:16px}

/* ===== Single post ===== */
.sm-bc{font-size:13px;color:var(--grey);margin-bottom:10px;display:flex;flex-wrap:wrap;align-items:center;row-gap:2px}
.sm-bc a{color:var(--grey)}
.sm-bc a:hover{color:var(--red)}
.sm-bc i{display:inline-block;width:6px;height:6px;border-top:1px solid currentColor;border-right:1px solid currentColor;transform:rotate(45deg);margin:0 10px 0 6px}
.sm-bc span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:280px}
.sm-sh{margin-bottom:20px}
.sm-chips{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:8px}
.sm-h1{font-size:30px;line-height:1.4;font-weight:500;margin:0 0 10px}
.sm-sm-row{display:flex;align-items:center;gap:10px}
.sm-av{flex:0 0 36px;width:36px;height:36px;border-radius:50%;overflow:hidden;background:var(--soft)}
.sm-av img{width:36px;height:36px;object-fit:cover;display:block}
.sm-smc{font-size:11px;color:var(--grey);line-height:1.5}
.sm-smc a{color:var(--txt)}
.sm-smc .sm-rt{display:inline-flex;align-items:center;gap:3px;margin-left:8px}
.sm-smc .sm-rt svg{width:12px;height:12px}
.sm-icons{margin-left:auto;display:flex;gap:8px}
.sm-ic{width:34px;height:34px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;color:#fff!important;border:0;padding:0;position:relative}
.sm-ic svg{width:16px;height:16px}
.sm-ic.cm{background:var(--blue)}
.sm-ic.sh{background:#3c5a99}
.sm-ic.vw{background:var(--red)}
.sm-ic em{position:absolute;top:-6px;right:-6px;min-width:18px;height:16px;padding:0 4px;border-radius:8px;background:var(--red);color:#fff;font-size:9px;font-style:normal;line-height:16px;text-align:center;border:1px solid #fff}
.sm-cover{margin:0 0 20px}
.sm-cover:empty{display:none}
.sm-cover img{display:block;width:100%;height:auto;max-height:420px;object-fit:cover}
.sm-cover a{display:block}
.sm-cover figcaption,.sm-cover .tr-caption{font-size:12px;color:var(--grey);margin-top:8px;text-align:left!important;line-height:1.4}
.sm-cover table{width:100%;border-collapse:collapse;margin:0!important}
.sm-cover td{padding:0!important}
.sm-wrap{display:flex;gap:20px;align-items:flex-start}
.sm-cont{flex:1;min-width:0}
.sm-stk{flex:0 0 120px;position:sticky;top:124px}
.sm-stk .sm-ph{width:120px;height:600px}
.sm-body{font-size:16px;line-height:1.5}
.sm-body p{margin:0 0 20px}
.sm-body h2{font-size:22px;margin:24px 0 12px}
.sm-body h3{font-size:19px;margin:22px 0 10px}
.sm-body a{color:var(--red)}
.sm-body img{height:auto}
.sm-body blockquote{margin:0 0 20px;padding:12px 18px;border-left:4px solid var(--red);background:var(--soft);color:var(--grey);font-style:italic}
.sm-body table{max-width:100%}
.sm-body .tr-caption{font-size:12px;color:var(--grey)}
.sm-body iframe{max-width:100%}
.sm-adin{margin:0 0 20px}
.sm-adin .sm-ph{width:468px;height:60px}
.sm-adpx{margin:0 0 20px}
.sm-adpx .sm-px{height:630px;background:var(--soft)}
.sm-adpx .sm-ph{width:300px;height:600px;background-color:var(--bg)}
.sm-adaf{margin:0 0 20px}
.sm-adaf .sm-ph{width:300px;height:250px}
.sm-tags{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:10px 0 0}
.sm-tagt{background:var(--blue);color:#fff;font-size:13px;padding:6px 8px;border-radius:2px;line-height:1.2}
.sm-tags a::before{content:'# '}
.sm-tags a{background:var(--soft);color:var(--red);font-size:13px;padding:6px 8px;border-radius:2px;line-height:1.2;border-left:3px solid var(--blue)}
.sm-next{display:flex;align-items:center;background:var(--red);color:#fff!important;margin-top:20px;height:60px;border-radius:2px;overflow:hidden}
.sm-next-img{flex:0 0 60px;height:60px;background:rgba(0,0,0,.2)}
.sm-next-img img{width:60px;height:60px;object-fit:cover;display:block}
.sm-next-t{flex:1;min-width:0;padding:0 12px;font-size:13px;font-weight:500;line-height:1.4;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.sm-next-ic{flex:0 0 30px;height:60px;background:#000;display:flex;align-items:center;justify-content:center}
.sm-next-ic svg{width:14px;height:14px}
.sm-next:hover .sm-next-t{color:var(--yel)}
.sm-shb{display:flex;align-items:center;justify-content:space-between;margin:20px 0}
.sm-shl{display:flex;gap:6px}
.sm-shl a{width:30px;height:30px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;color:#fff!important}
.sm-shl svg{width:15px;height:15px}
.s-fb{background:#3c5a99}.s-x{background:#0f1419}.s-tg{background:#0088cc}.s-wa{background:#25d366}.s-pin{background:#bd081c}.s-ig{background:#e4405f}.s-yt{background:#cd201f}.s-tt{background:#010101}.s-rss{background:#ee802f}.s-in{background:#0077b5}.s-wp{background:#21759b}
.sm-rel{margin:0 0 20px}
.sm-rg{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.sm-rg-i{display:block;min-width:0}
.sm-rg-img{position:relative;display:block;overflow:hidden;border-radius:2px}
.sm-rg-img img{display:block;width:100%;aspect-ratio:213/134;object-fit:cover;transition:transform .3s}
.sm-rg-i:hover img{transform:scale(1.05)}
.sm-rg-img .sm-chip{position:absolute;left:8px;bottom:8px}
.sm-rg-i b{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;font-size:14px;font-weight:500;line-height:1.4;margin-top:8px}
.sm-cmt{margin:0 0 20px}
.sm-cmt .comment-form,.sm-cmt #comment-holder{max-width:100%}
.sm-cmt .comments h4,.sm-cmt h3.title{display:none}
.sm-cmt .comment-thread ol{list-style:none;margin:0;padding:0}
.sm-cmt .comment{margin:0 0 16px;padding:12px 0;border-bottom:1px solid var(--bd)}
.sm-cmt .comment-block{margin-left:0}
.sm-cmt .avatar-image-container{float:left;margin-right:10px;border-radius:50%;overflow:hidden;width:36px;height:36px}
.sm-cmt .avatar-image-container img{width:36px;height:36px}
.sm-cmt .comment-header .user{font-weight:600}
.sm-cmt .comment-header .datetime{font-size:11px;color:var(--grey);margin-left:8px}
.sm-cmt .comment-content{margin:6px 0 0 46px}
.sm-cmt .comment-actions{margin-left:46px;font-size:12px}
.sm-cmt .comment-replies{margin-left:30px}
.sm-cmt .comment-footer a,.sm-cmt .comment-actions a{color:var(--blue)}
.sm-cmt-note{font-size:13px;color:var(--grey);margin:0 0 10px}

/* share modal */
.sm-modal{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:100001;display:none;align-items:center;justify-content:center;padding:16px}
.sm-modal.open{display:flex}
.sm-mbox{background:var(--bg);border-radius:4px;padding:20px;width:100%;max-width:380px;position:relative}
.sm-mbox h4{font-size:16px;margin:0 0 14px}
.sm-mbox .sm-shl{gap:10px}
.sm-mbox .sm-shl a{width:40px;height:40px}
.sm-mbox .sm-x{top:-12px;right:-12px}
.sm-copy{margin-top:14px;display:flex;gap:6px}
.sm-copy input{flex:1;min-width:0;height:34px;border:1px solid var(--bd);background:var(--soft);color:var(--txt);padding:0 10px;font:13px Poppins,Arial,sans-serif}
.sm-copy button{background:var(--blue);color:#fff;border:0;padding:0 12px;border-radius:2px;font-size:13px}

/* ===== Footer ===== */
.sm-ft{margin-top:20px;border-top:1px solid var(--bd);background:var(--ft);padding:30px 0 0;color:var(--grey2)}
.sm-ft-g{display:grid;grid-template-columns:minmax(0,2.4fr) repeat(3,minmax(0,1fr));gap:30px}
.sm-ft-logo{margin-bottom:14px}
.sm-ft-logo .sm-logo-t{font-size:27px}
.sm-ft-logo img{max-height:40px;width:auto}
.sm-ct li{display:flex;gap:12px;font-size:13px;margin-bottom:12px;line-height:1.6}
.sm-ct svg{flex:0 0 18px;width:18px;height:18px;color:var(--txt);margin-top:1px}
.sm-ct a{color:var(--grey2)}
.sm-ft .sm-st{font-size:16px;margin-bottom:12px}
.sm-fl-list li{font-size:13px;line-height:1.6;margin-bottom:8px}
.sm-fl-list a{color:var(--grey2)}
.sm-fl-list a:hover{color:var(--red)}
.sm-fl-list.hash a::before{content:'#';color:var(--red);margin-right:6px}
.sm-soc{display:flex;gap:6px;flex-wrap:wrap;margin:24px 0 0}
.sm-soc a{width:28px;height:28px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;color:#fff!important}
.sm-soc svg{width:14px;height:14px}
.sm-fb{border-top:1px solid var(--bd);margin-top:20px;padding:16px 0 20px;font-size:13px}
.sm-fb-l{display:flex;flex-wrap:wrap;margin-bottom:8px}
.sm-fb-l a{color:var(--txt)}
.sm-fb-l a:not(:last-child)::after{content:'\2044';margin:0 8px;color:var(--grey)}
.sm-fb-c a{color:var(--txt)}

/* ===== Drawer (menu HP) ===== */
.sm-ov{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:99998;opacity:0;visibility:hidden;transition:.25s}
.sm-dw{position:fixed;top:0;bottom:0;left:0;width:min(400px,86vw);background:var(--bg);z-index:99999;transform:translateX(-102%);transition:transform .3s ease;overflow-y:auto;padding:16px 20px 30px}
body.dw-open{overflow:hidden}
body.dw-open .sm-ov{opacity:1;visibility:visible}
body.dw-open .sm-dw{transform:none}
.sm-dw-h{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}
.sm-dw-h .sm-logo-t{font-size:22px}
.sm-dw-h img{max-height:34px;width:auto}
.sm-dw-x{width:30px;height:30px;border:0;background:var(--soft);border-radius:50%;color:var(--txt);font-size:18px;line-height:1;padding:0}
.sm-acc{border-top:1px solid var(--bd)}
.sm-acc>button{width:100%;display:flex;align-items:center;justify-content:space-between;background:none;border:0;padding:12px 0;color:var(--txt);font-weight:600;font-size:15px;text-align:left}
.sm-acc>button svg{width:14px;height:14px;transition:transform .2s}
.sm-acc.open>button svg{transform:rotate(180deg)}
.sm-acc>div{display:none;padding:0 0 12px}
.sm-acc.open>div{display:block}
.sm-dw-cat{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.sm-dw-cat a{display:flex;align-items:center;gap:8px;font-size:13px;padding:6px;background:var(--soft);border-radius:2px}
.sm-dw-cat img,.sm-dw-cat i{width:30px;height:30px;flex:0 0 30px;border-radius:2px;object-fit:cover}
.sm-dw-cat i{display:flex;align-items:center;justify-content:center;font-style:normal;color:#fff;font-weight:600;background:linear-gradient(80deg,var(--red),var(--blue))}
.sm-dw-l a{display:block;font-size:13px;line-height:2.2}
.sm-dw .sm-soc{margin-top:16px}
.sm-dw-s{margin:0 0 14px}
.sm-dw-s input{width:100%}

/* back to top */
.sm-top-btn{position:fixed;right:24px;bottom:24px;width:36px;height:36px;border-radius:50%;border:2px solid var(--txt);background:var(--bg);color:var(--txt);display:flex;align-items:center;justify-content:center;z-index:997;opacity:0;visibility:hidden;transition:.25s;padding:0}
.sm-top-btn.show{opacity:1;visibility:visible}
.sm-top-btn svg{width:18px;height:18px}

/* skeleton */
.sm-blk{min-height:40px}
.sm-sk{background:linear-gradient(90deg,var(--soft) 25%,rgba(0,0,0,.09) 50%,var(--soft) 75%);background-size:300% 100%;animation:smsk 1.4s infinite}
@keyframes smsk{from{background-position:100% 0}to{background-position:0 0}}
.sm-sk-sl{height:571px;margin-bottom:20px}
.sm-sk-cr{height:262px;margin-bottom:20px}
.sm-sk-sb{height:420px;margin-bottom:20px}

/* ===== Dark ===== */
body.dark .sm-arr{background:#333;color:#fff}
body.dark .sm-gbox,body.dark .sm-gbox2{background:#2a2a2a!important}
body.dark .sm-sl-t{border-top-color:#555}
body.dark .sm-sl-t.on{border-top-color:var(--red)}
body.dark .sm-search input{background:#333}
body.dark .sm-x{border-color:#333}
body.dark .sm-ph{color:#999}

/* ===== Responsive ===== */
@media (max-width:1199px){.sm-fl{display:none!important}}
@media (max-width:991px){
  .sm-grid,.is-home .sm-grid{grid-template-columns:minmax(0,1fr);grid-template-areas:"ma" "sa" "fw" "mc" "sc"}
  .sm-side{position:static}
  .sm-side{margin-top:10px}
  .sm-vt{display:block}
  .sm-vt.closed{display:none}
  .sm-date{display:none}
  .sm-burger,.sm-sbtn{display:inline-flex}
  .sm-search{display:none;position:absolute;left:0;right:0;top:60px;z-index:20;height:44px;background:var(--hdr);padding:5px 16px;box-shadow:0 6px 10px rgba(0,0,0,.08)}
  .sm-search input{width:100%}
  /* HP: input 16px agar browser tidak memperbesar halaman saat kolom cari dibuka */
  .sm-search input,.sm-copy input{font-size:16px}
  .sm-search button{right:20px;top:7px}
  .sm-hd.sopen .sm-search{display:block}
  .sm-top{gap:8px;position:relative}
  .sm-logo-t{font-size:22px}
  .sm-logo img{max-height:34px}
  .sm-nav{overflow-x:auto;overflow-y:hidden;scrollbar-width:none}
  .sm-nav::-webkit-scrollbar{display:none}
  .sm-menu{gap:24px;width:max-content;padding-right:16px}
  .sm-sub,.sm-menu>li.sm-more-li{display:none!important}
  .sm-menu>li>a svg{display:none}
  .sm-stk{display:none}
  .sm-h1{font-size:22px}
  .sm-ft-g{grid-template-columns:repeat(3,minmax(0,1fr))}
  .sm-ft-g>div:first-child{grid-column:1/-1}
}
@media (max-width:767px){
  .sm-ad-hd .sm-ph{width:100%;height:auto;aspect-ratio:970/250}
  .sm-bn-l{padding-right:26px;font-size:13px}
  .sm-bn-i{width:240px}
  .sm-sl-m{height:auto;aspect-ratio:672/384}
  .sm-sl-info h3{font-size:16px}
  .sm-sl-t span{min-height:72px}
  .sm-sl-t span b{font-size:13px}
  .sm-cr-i{flex-basis:calc((100% - 16px) / 2)}
  .sm-gb{grid-template-columns:repeat(2,minmax(0,1fr))}
  .sm-rg{grid-template-columns:repeat(2,minmax(0,1fr))}
  .sm-ft-g{grid-template-columns:repeat(2,minmax(0,1fr))}
  .sm-ft-g>div:nth-child(4){grid-column:1/-1}
}
@media (max-width:700px){
  .sm-thumb{flex:0 0 110px;max-width:110px}
  .sm-thumb img{aspect-ratio:110/80}
}
@media (max-width:550px){
  /* seperti demo: 4 gambar kecil, judul disembunyikan */
  .sm-sl-t span{display:none}
}
@media (max-width:600px){
  .sm-et{font-size:14px;margin-bottom:6px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
  .sm-ex{display:none}
  .sm-box{gap:12px;align-items:flex-start}
  .sm-arr{width:38px;height:38px}
  .sm-gbox,.sm-gbox2{padding:12px}
  .sm-top-btn{right:14px;bottom:14px}
  .sm-adpx .sm-px{height:520px}
  .sm-ptitle{font-size:20px}
}
@media (max-width:400px){
  .sm-icons .sm-ic.vw{display:none}
  .sm-av{display:none}
}

.tbd-license-gate[hidden],.tbd-license-shield[hidden],.tbd-license-status[hidden],#tbd-license-context[hidden]{display:none!important}
.tbd-license-gate,.tbd-license-gate *,.tbd-license-status,.tbd-license-status *{box-sizing:border-box}
.tbd-license-gate{position:fixed;inset:0;z-index:2147483000;display:grid;place-items:center;overflow:auto;padding:24px 16px;background:rgba(15,23,42,.55);font-family:Arial,system-ui,sans-serif;color:#172339;text-align:left;line-height:1.6}
.tbd-license-card{width:100%;max-width:460px;margin:auto;padding:30px;background:#fff;border:1px solid #e5eaf2;border-radius:22px;box-shadow:0 24px 80px #0f172a40}
.tbd-license-brand{display:inline-flex;align-items:center;gap:8px;color:#172339!important;text-decoration:none!important;font:bold 21px/1.3 Arial,sans-serif;letter-spacing:-.6px}
.tbd-license-brand b{color:#2456d9}.tbd-license-logo{position:relative;display:grid;place-items:center;width:30px;height:30px;border-radius:9px;color:#fff;background:#2456d9;font:bold 24px/1 Arial,sans-serif;letter-spacing:0}.tbd-license-logo>span{position:absolute;right:5px;bottom:5px;width:6px;height:6px;border-radius:50%;background:#ffb300}
.tbd-license-symbol{display:grid;place-items:center;width:54px;height:54px;margin-top:28px;margin-bottom:16px;border-radius:15px;background:#edf2ff;color:#2456d9}
.tbd-license-eyebrow{margin:0 0 8px!important;color:#526178;font:bold 11px/1.5 Arial,sans-serif;letter-spacing:1.3px}
.tbd-license-card h2{margin:0 0 14px!important;padding:0;color:#172339;font:bold 26px/1.25 Arial,sans-serif;letter-spacing:-.7px;overflow-wrap:anywhere}
.tbd-license-card #tbd-license-description{margin:0 0 24px!important;color:#526178;font:15px/1.7 Arial,sans-serif;overflow-wrap:anywhere}
.tbd-license-card strong{color:#172339;font-weight:700}
.tbd-license-actions{display:grid;gap:10px}
.tbd-license-actions a{display:flex;justify-content:center;align-items:center;min-height:48px;padding:12px 16px;border:1px solid #2456d9;border-radius:11px;background:#2456d9;color:#fff!important;text-decoration:none!important;font:bold 15px/1.45 Arial,sans-serif;text-align:center;overflow-wrap:anywhere}
.tbd-license-actions a:hover{background:#173fa9;border-color:#173fa9}.tbd-license-actions .tbd-license-secondary{background:#fff;color:#2456d9!important;border-color:#d3ddef}.tbd-license-actions .tbd-license-secondary:hover{background:#f5f7fb}
#tbd-license-check{display:block;margin:18px auto 0;padding:6px 3px;border:0;background:transparent;color:#526178;font:14px/1.5 Arial,sans-serif;text-align:center;text-decoration:underline;text-underline-offset:4px;cursor:pointer}
.tbd-license-gate :focus-visible,.tbd-license-status button:focus-visible{outline:3px solid #9db5ff;outline-offset:3px}
.tbd-license-modal{overflow:hidden}.tbd-license-shield{position:fixed;inset:0;z-index:2147482000;background:transparent}
.tbd-license-status{position:fixed;z-index:2147483001;left:50%;bottom:18px;transform:translateX(-50%);width:calc(100% - 32px);max-width:440px;padding:16px 18px;border:1px solid #e5eaf2;border-radius:12px;background:#fff;color:#526178;box-shadow:0 6px 30px #0f172a20;font:14px/1.6 Arial,sans-serif}
.tbd-license-status button{display:block;margin-top:8px;padding:7px 12px;border:0;border-radius:8px;background:#2456d9;color:#fff;font:bold 13px/1.5 Arial,sans-serif;cursor:pointer}
@media(max-width:380px){.tbd-license-card{padding:24px 20px}.tbd-license-card h2{font-size:23px}}


/* Native license input is invisible on the public site. */
.tb-license-settings{display:none!important}

head.b:template-skin:
/* TemaBlogger License Key: native Layout controls remain editable. */
body#layout .tb-license-settings{display:block!important;width:auto!important;clear:both!important;margin:0 0 16px!important;padding:12px!important;border:1px solid #d8e3f5!important;border-radius:12px!important;background:#f0f5ff!important}
body#layout .tb-license-settings .add_widget{display:none!important}

/* TemaBlogger: CSS khusus panel native Blogger, kompatibel parser legacy. */
body#layout { min-width:0!important; max-width:1120px!important; margin:0 auto!important; padding:16px!important; background:#eef2f6!important; color:#26364c!important; font:14px/1.5 Arial,sans-serif!important; text-align:left!important; }
body#layout .tbly-pass { display:contents!important; }
body#layout .tbly-pass:before,body#layout .tbly-pass:after { content:none!important; display:none!important; }
body#layout .tbly-ignore { display:none!important; }
body#layout .tbly-group { display:block!important; clear:both!important; float:none!important; position:relative!important; top:auto!important; bottom:auto!important; left:auto!important; right:auto!important; width:auto!important; min-width:0!important; max-width:none!important; height:auto!important; min-height:0!important; margin:0 0 20px!important; padding:18px!important; overflow:visible!important; transform:none!important; border:1px solid #d4deeb!important; border-radius:8px!important; background:#f8fafc!important; color:#26364c!important; text-align:left!important; }
body#layout .tbly-group:before { display:block!important; position:static!important; clear:both!important; margin:0 0 16px!important; padding:0 0 10px!important; border-bottom:1px solid #dce4ef!important; font:700 16px/1.4 Arial,sans-serif!important; color:#d9091b!important; background:none!important; }
body#layout .tbly-group:after { display:block!important; position:static!important; clear:both!important; margin:0!important; padding:4px 0 0!important; font:12px/1.6 Arial,sans-serif!important; color:#60718a!important; background:none!important; }
body#layout div.section>h4 { margin:0 0 10px!important; padding:0!important; font:700 13px/1.5 Arial,sans-serif!important; color:#34455c!important; word-wrap:break-word!important; }
body#layout div.section .widget { float:none!important; width:auto!important; min-width:0!important; max-width:none!important; height:auto!important; min-height:0!important; margin:10px 0 0!important; }
body#layout div.section .widget-content { min-width:0!important; border-radius:6px!important; background:#fff!important; }
body#layout div.section .layout-title { color:#394b62!important; }
body#layout div.section .layout-widget-description { color:#6a7a90!important; }
body#layout div.section .editlink,body#layout div.section .layout-widget-state { visibility:visible!important; opacity:1!important; }
body#layout div.section .add_widget { display:none!important; }

body#layout:before { content:"SaeMedia - Pengaturan Tata Letak"; display:block; margin:0 0 18px; color:#d9091b; font:700 22px/1.4 Arial,sans-serif; }
body#layout #iklan-atas-hp { display:block!important; position:relative!important; float:none!important; width:auto!important; min-width:0!important; max-width:none!important; height:auto!important; min-height:0!important; margin:0 0 14px!important; padding:0!important; overflow:visible!important; background:transparent!important; border:0!important; border-radius:0!important; text-align:left!important; }
body#layout #header { display:block!important; position:relative!important; float:none!important; width:auto!important; min-width:0!important; max-width:none!important; height:auto!important; min-height:0!important; margin:0 0 14px!important; padding:0!important; overflow:visible!important; background:transparent!important; border:0!important; border-radius:0!important; text-align:left!important; }
body#layout #pengaturan-menu { display:block!important; position:relative!important; float:none!important; width:auto!important; min-width:0!important; max-width:none!important; height:auto!important; min-height:0!important; margin:0 0 14px!important; padding:0!important; overflow:visible!important; background:transparent!important; border:0!important; border-radius:0!important; text-align:left!important; }
